13	// GetLinkMetadata gets metadata for a link.
14	func (*APIV1Service) GetLinkMetadata(_ context.Context, request *v1pb.GetLinkMetadataRequest) (*v1pb.LinkMetadata, error) {
15		return getLinkMetadata(request.GetUrl())
16	}
17	
18	// BatchGetLinkMetadata gets metadata for links.
19	func (*APIV1Service) BatchGetLinkMetadata(_ context.Context, request *v1pb.BatchGetLinkMetadataRequest) (*v1pb.BatchGetLinkMetadataResponse, error) {
20		if len(request.Urls) == 0 {
21			return nil, status.Errorf(codes.InvalidArgument, "urls are required")
22		}
23		if len(request.Urls) > maxBatchGetLinkMetadata {
24			return nil, status.Errorf(codes.InvalidArgument, "too many urls (max %d)", maxBatchGetLinkMetadata)
25		}
26	
27		linkMetadata := make([]*v1pb.LinkMetadata, 0, len(request.Urls))
28		for _, url := range request.Urls {
29			metadata, err := getLinkMetadata(url)
30			if err != nil {
31				return nil, err
32			}
33			linkMetadata = append(linkMetadata, metadata)
34		}
35	
36		return &v1pb.BatchGetLinkMetadataResponse{
37			LinkMetadata: linkMetadata,
38		}, nil
39	}
40	
41	func getLinkMetadata(inputURL string) (*v1pb.LinkMetadata, error) {
42		url := strings.TrimSpace(inputURL)
43		if url == "" {
44			return nil, status.Errorf(codes.InvalidArgument, "url is required")
45		}
46		htmlMeta, err := fetchHTMLMeta(url)
47		if err != nil {
48			return nil, status.Errorf(codes.InvalidArgument, "failed to fetch link metadata: %v", err)
49		}
50	
51		return &v1pb.LinkMetadata{
52			Url:         inputURL,
53			Title:       htmlMeta.Title,
54			Description: htmlMeta.Description,
55			Image:       htmlMeta.Image,
56		}, nil
57	}
